"""Expectations generated by an independent Decimal event tree, not production code."""
import json
from copy import deepcopy
from pathlib import Path

import pytest
from hypothesis import given, settings
from hypothesis import strategies as st
from tarkov_sim_core.api import calculate_analytic_json, compare_json, simulate_json
from tarkov_sim_core.models import ArmorLayer, ArmorLayerType, ArmorMaterial, ProjectileState
from tarkov_sim_core.rulesets import CurrentApproximation

CASES = json.loads((Path(__file__).parent/"fixtures/independent_cases_2026_10_25.json").read_text())


@pytest.mark.parametrize("case", CASES, ids=lambda c: c["id"])
def test_independent_decimal_cases(case):
    payload = case["input"]
    exact = payload["shot_count"] == payload["ammo"]["projectile_count"] == 1
    actual = json.loads((calculate_analytic_json if exact else simulate_json)(payload))["result"]
    for key in ("final_penetration_probability", "expected_health_damage", "expected_blunt_damage", "expected_burst_total_damage"):
        # Enumeration is exact; seeded MC accepts sampling error, never changes reference values.
        tolerance = 1e-10 if exact else (.008 if "probability" in key else .8)
        assert actual[key] == pytest.approx(case["expected"][key], abs=tolerance)


@given(level=st.integers(1,6), current=st.floats(0,100,allow_nan=False),
       pen=st.floats(0,200,allow_nan=False), increment=st.floats(0,100,allow_nan=False))
@settings(max_examples=600, deadline=None, derandomize=True)
def test_probability_bounds_monotonicity_and_broken_bypass(level, current, pen, increment):
    armor = ArmorLayer("property", "Property plate", ArmorLayerType.PLATE, level,
                       current,100,100,ArmorMaterial.CERAMIC,.6,.1,True)
    rules = CurrentApproximation()
    state = ProjectileState(50,pen,armor_damage_percent=50)
    p = rules.penetration_probability(state,armor)
    q = rules.penetration_probability(ProjectileState(50,pen+increment),armor)
    assert 0 <= p <= q+1e-12 <= 1+1e-12
    assert 0 <= rules.calculate_armor_damage(state,armor,True) <= current
    armor.current_durability = 0
    assert rules.penetration_probability(state,armor) == 1
    assert rules.calculate_post_penetration_state(state,armor).remaining_damage == 50


def test_api_default_distance_is_off():
    payload = deepcopy(CASES[-2]["input"])
    payload.pop("enable_distance_decay")
    actual = json.loads(calculate_analytic_json(payload))
    payload["distance_m"] = 0
    zero = json.loads(calculate_analytic_json(payload))
    assert actual["result"]["expected_health_damage"] == zero["result"]["expected_health_damage"]


@pytest.mark.parametrize("field,value", [("enabled","false"),("enabled",0),("is_hard_armor",1)])
def test_armor_flags_are_strict_booleans(field,value):
    payload = deepcopy(CASES[0]["input"])
    payload["armor_layers"][0][field] = value
    assert not json.loads(calculate_analytic_json(payload))["ok"]


@pytest.mark.parametrize("value", [None, [], "not-json", {"scenarios": "wrong"}, {"scenarios": []}])
def test_compare_reports_invalid_inputs_instead_of_raising(value):
    assert not json.loads(compare_json(value))["ok"]
